-- Combiflam (ibuprofen + acetaminophen)
insert into public.medicine_details (medicine_id, medicine_activity, uses, side_effects, composition, manufacturer_details, generation_status, generated_at)
values (1, 'Ibuprofen tablets contain ibuprofen which possesses analgesic and antipyretic activities. Its mode of action, like that of other NSAIDs, is not completely understood, but may be related to prostaglandin synthetase inhibition. In clinical studies in patients with rheumatoid arthritis and osteoarthritis, ibuprofen tablets have been shown to be comparable to aspirin in controlling pain and inflammation and to be associated with a statistically significant reduction in the milder gastrointestinal side effects (see ADVERSE REACTIONS ).', 'Temporarily relieves minor aches and pains due to: headache toothache backache menstrual cramps the common cold muscular aches minor pain of arthritis temporarily reduces fever', 'The most frequent type of adverse reaction occurring with ibuprofen tablets is gastrointestinal. In controlled clinical trials the percentage of patients reporting one or more gastrointestinal complaints ranged from 4% to 16%. In controlled studies when ibuprofen tablets were compared to aspirin and indomethacin in equally effective doses, the overall incidence of gastrointestinal complaints was about half that seen in either the aspirin- or indomethacin-treated patients. Adverse reactions observed during controlled clinical trials at an incidence greater than 1% are listed in the table.', 'Active ingredients: Ibuprofen + Acetaminophen. Marketed as: Combines ibuprofen and paracetamol to relieve pain, inflammation, and fever. Ingredient names normalised against RxNorm (RxCUI 5640, 161).', 'Marketed in India by Sanofi India. Reference label filed by CVS Pharmacy (openFDA).', 'generated', now())
on conflict (medicine_id) do update set
  medicine_activity = excluded.medicine_activity,
  uses = excluded.uses,
  side_effects = excluded.side_effects,
  composition = excluded.composition,
  manufacturer_details = excluded.manufacturer_details,
  generation_status = excluded.generation_status,
  generated_at = excluded.generated_at,
  updated_at = now();

