insert into public.medicine_details (medicine_id, medicine_activity, uses, side_effects, composition, manufacturer_details, generation_status, generated_at)
values (5, 'Pain reliever', 'For the temporary relief of minor aches and pains or as recommended by your doctor. Because of its delayed action, this product will not provide fast relief of headaches or other symptoms needing immediate relief. ask your doctor about other uses for safety coated 81 mg aspirin', 'Stop use and ask a doctor if an allergic reaction occurs. Seek medical help right away. you experience any of the following signs of stomach bleeding: feel faint vomit blood have bloody or black stool have stomach pain that does not get better pain gets worse or lasts more than 10 days redness or swelling is present ringing in the ears or loss of hearing occurs new symptoms occur These could be signs of a serious condition', 'Active ingredient: Aspirin. Marketed as: Low-dose aspirin tablet used to reduce the risk of heart attack and stroke. Ingredient names normalised against RxNorm (RxCUI 1191).', 'Marketed in India by USV Private Limited. Reference label filed by P & L Development, LLC (openFDA).', 'generated', now())
