insert into public.medicine_details (medicine_id, medicine_activity, uses, side_effects, composition, manufacturer_details, generation_status, generated_at)
values (88, 'Cefixime is a semisynthetic cephalosporin antibacterial drug [see Microbiology (12.4) ].', 'Cefixime for oral suspension is a cephalosporin antibacterial drug indicated in the treatment of adults and pediatric patients six months and older with the following infections: Uncomplicated Urinary Tract Infections (1.1) Otitis Media (1.2) Pharyngitis and Tonsillitis (1.3) Acute Exacerbations of Chronic Bronchitis (1.4) Uncomplicated Gonorrhea (cervical/urethral) (1.5) To reduce the development of drug-resistant bacteria and maintain the effectiveness of cefixime for oral suspension and other antibacterial drugs, cefixime for oral suspension should be used only to tr…', 'Most common adverse reactions are gastrointestinal such as diarrhea (16%), nausea (7%), loose stools (6%), abdominal pain (3%), dyspepsia (3%), and vomiting. (6) To report SUSPECTED ADVERSE REACTIONS, contact Aurobindo Pharma USA, Inc. at 1-866-850-2876 or FDA at 1-800-FDA-1088 or www.fda.gov/m edwatch.', 'Active ingredient: Cefixime. Marketed as: Cefixime antibiotic tablet for bacterial infections. Ingredient names normalised against RxNorm (RxCUI 25033).', 'Marketed in India by FDC Limited. Reference label filed by Aurobindo Pharma Limited (openFDA).', 'generated', now())
