-- Budecort Inhaler (budesonide)
insert into public.medicine_details (medicine_id, medicine_activity, uses, side_effects, composition, manufacturer_details, generation_status, generated_at)
values (89, 'BUDESONIDE AND FORMOTEROL FUMARATE DIHYDRATE INHALATION AEROSOL BUDESONIDE AND FORMOTEROL FUMARATE DIHYDRATE INHALATION AEROSOL contains both budesonide and formoterol; therefore, the mechanisms of action described below for the individual components apply to BUDESONIDE AND FORMOTEROL FUMARATE DIHYDRATE INHALATION AEROSOL. These drugs represent two classes of medications (a synthetic corticosteroid and a long-acting selective beta 2 -adrenoceptor agonist) that have different effects on clinical, physiological, and inflammatory indices of COPD and asthma.', 'Use s Temporarily relieves these symptoms of hay fever or other upper respiratory allergies: • nasal congestion • runny nose • itchy nose • sneezing', 'LABA use may result in the following: • Serious asthma-related events – hospitalizations, intubations, death [see Warnings and Precautions (5.1) ]. • Cardiovascular and central nervous system effects [see Warnings and Precautions (5.12) ].', 'Active ingredient: Budesonide. Marketed as: Budesonide inhaler used for long-term control of asthma inflammation. Ingredient names normalised against RxNorm (RxCUI 19831).', 'Marketed in India by Cipla. Reference label filed by Rugby Laboratories (openFDA).', 'generated', now())
